import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"支持策略","description":"","frontmatter":{},"headers":[],"relativePath":"zh/support.md","filePath":"zh/support.md","lastUpdated":1785029508000}`),a={name:`zh/support.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="支持策略" tabindex="-1">支持策略 <a class="header-anchor" href="#支持策略" aria-label="Permalink to “支持策略”">​</a></h1><p>本页定义 <code>main</code> 分支由 CI 持续验证的运行环境。Beta 阶段的接口仍可能变化，但发布前， 这里列出的环境必须通过同一套公开 API 一致性与打包门禁。</p><h2 id="node-js" tabindex="-1">Node.js <a class="header-anchor" href="#node-js" aria-label="Permalink to “Node.js”">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>支持版本</th><th>验证证据</th></tr></thead><tbody><tr><td><code>fontmin-rs</code> CLI 与 Node API</td><td>Node.js 22、24、26</td><td>Linux、macOS、Windows 完整测试矩阵</td></tr><tr><td>Native binding packages</td><td>下列 target 上的 Node-API 8</td><td>Native 构建与 tarball consumer smoke test</td></tr><tr><td><code>@fontmin-rs/wasm</code> 工具链</td><td>Node.js 22 或更高</td><td>Typecheck、构建、Vitest 与浏览器包 smoke test</td></tr></tbody></table><p>发布的 <code>fontmin-rs</code> 包声明 <code>node &gt;=22.0.0</code>。更新的 Node.js major 在加入 CI 矩阵前 按 best-effort 支持。加载可执行的 TypeScript、MTS、MJS、CJS 配置也要求 Node.js 22 或更高版本。</p><h2 id="native-平台" tabindex="-1">Native 平台 <a class="header-anchor" href="#native-平台" aria-label="Permalink to “Native 平台”">​</a></h2><p>Release workflow 会构建并打包以下精确 target：</p><table tabindex="0"><thead><tr><th>操作系统</th><th>CPU</th><th>Runtime</th></tr></thead><tbody><tr><td>macOS</td><td>x64</td><td>Darwin native binding</td></tr><tr><td>macOS</td><td>arm64</td><td>Darwin native binding</td></tr><tr><td>Windows</td><td>x64</td><td>MSVC native binding</td></tr><tr><td>Windows</td><td>arm64</td><td>MSVC native binding</td></tr><tr><td>Linux</td><td>x64</td><td>glibc</td></tr><tr><td>Linux</td><td>x64</td><td>musl</td></tr><tr><td>Linux</td><td>arm64</td><td>glibc</td></tr><tr><td>Linux</td><td>arm64</td><td>musl</td></tr></tbody></table><p>Node <code>runtime: &quot;auto&quot;</code> 会优先加载对应 native package，无法加载时回退到 WASM。 <code>runtime: &quot;native&quot;</code> 是硬性要求；加载失败会返回错误，不会静默切换行为。</p><h2 id="浏览器-wasm" tabindex="-1">浏览器 WASM <a class="header-anchor" href="#浏览器-wasm" aria-label="Permalink to “浏览器 WASM”">​</a></h2><p>浏览器包会在当前 Playwright Chromium、Firefox 和 WebKit 中测试。其公开边界为异步、 纯内存 API，不支持文件路径、glob、磁盘缓存、CLI 或任意 Node.js plugin hook。</p><p>Native 与 WASM 对每个内置 transform、preset、输出 metadata 契约和 malformed input 诊断运行相同的语义一致性 corpus。字节级完全相同不属于兼容性承诺。</p><h2 id="rust-工具链" tabindex="-1">Rust 工具链 <a class="header-anchor" href="#rust-工具链" aria-label="Permalink to “Rust 工具链”">​</a></h2><ul><li><strong>MSRV：</strong> Rust 1.88.0，由 workspace metadata 声明，并通过 <code>cargo check --locked --workspace --all-targets --all-features</code> 验证。</li><li><strong>固定开发与发布工具链：</strong> Rust 1.97.1，用于格式化、Clippy、测试、覆盖率、 native/WASM 构建和发布。</li><li><strong>Fuzzing：</strong> 当前 nightly，仅用于独立 cargo-fuzz workspace 和定时 AddressSanitizer 任务。</li></ul><p>每次准备 beta/RC 或依赖要求升级时复核固定工具链。升级必须成为显式仓库提交并通过完整 release gate。1.0 前提高 MSRV 必须提供 Changelog 和迁移说明；1.0 后至少通过 minor 版本发布。</p><h2 id="支持边界" tabindex="-1">支持边界 <a class="header-anchor" href="#支持边界" aria-label="Permalink to “支持边界”">​</a></h2><p>只有本矩阵列出的环境会阻断发布。其他操作系统、CPU、Node.js 版本和浏览器可能通过 WASM 正常运行，但在进入 CI 前均按 best-effort 支持。报告问题时请附带 runtime、 target、输入格式和诊断输出。</p>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};